{
  "missing_information": [
    {
      "category": "Tool Selection Logic",
      "gap": "Rules or criteria governing which measurement tool is assigned to a given wafer, and whether assignment is manual or automated",
      "why_it_matters": "Without knowing the routing logic, the branching structure of the process model cannot be reconstructed or automated"
    },
    {
      "category": "Per-Tool Step Sequence",
      "gap": "Ordered list of preparation, calibration, and measurement steps for each tool variant",
      "why_it_matters": "The workflow description notes steps differ by tool; exact sequences are needed to model each variant correctly"
    },
    {
      "category": "Result Recording and Storage",
      "gap": "How the engineer records the measurement result and where it is stored afterward",
      "why_it_matters": "Determines whether result capture is a manual bottleneck or can be automated, and where data resides for downstream use"
    },
    {
      "category": "Tool Data Export Capability",
      "gap": "Whether tools can export data programmatically via files, network interfaces, or APIs",
      "why_it_matters": "Directly affects feasibility of automating result retrieval and integration with other systems"
    },
    {
      "category": "Out-of-Spec Handling",
      "gap": "Defined thresholds for acceptable results and the escalation or rework path when a result is out of range",
      "why_it_matters": "Exception paths are critical for complete process modeling and cannot be inferred from the initial description"
    },
    {
      "category": "Workflow Triggers and Boundaries",
      "gap": "What initiates the measurement workflow and what signal marks its completion for downstream processes",
      "why_it_matters": "Process mining and automation require clear start and end events to scope the workflow and connect it to adjacent processes"
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "What criteria or rules determine which measurement tool is assigned to a given wafer — for example, wafer type, lot specification, or tool availability — and is that assignment made by a person, a scheduling system, or some other mechanism?",
      "targets": ["Tool Selection Logic"],
      "source_ids": ["C2"],
      "selection_reason": "C2 combines both the criteria and the assignment mechanism in one focused question, making it more complete than C1 while covering the same core gap"
    },
    {
      "id": "Q2",
      "question": "For each tool variant used in this workflow, can you list the discrete preparation, calibration, and measurement steps in the order they are performed, highlighting where the steps differ between tools?",
      "targets": ["Per-Tool Step Sequence"],
      "source_ids": ["C4"],
      "selection_reason": "C4 asks for ordered, per-tool step sequences including calibration, which is more actionable for process modeling than the higher-level C3"
    },
    {
      "id": "Q3",
      "question": "How does the engineer record the measurement result — for example, manual entry into a form or system, automatic capture from the tool, or a paper log — and where is that result stored after recording?",
      "targets": ["Result Recording and Storage"],
      "source_ids": ["C6"],
      "selection_reason": "C6 covers both the recording method and the storage destination in one question, providing more complete information than C5 alone"
    },
    {
      "id": "Q4",
      "question": "Do the measurement tools have any data export capability, such as file outputs, network interfaces, or APIs, that could be used to retrieve results programmatically?",
      "targets": ["Tool Data Export Capability"],
      "source_ids": ["C7"],
      "selection_reason": "C7 addresses automation feasibility for result capture specifically, a distinct concern from how the engineer currently records results, and is not covered by other selected questions"
    },
    {
      "id": "Q5",
      "question": "Are there defined acceptance thresholds for the measurement result, and if a result falls outside those thresholds, what is the defined escalation or rework path?",
      "targets": ["Out-of-Spec Handling"],
      "source_ids": ["C8", "C9"],
      "selection_reason": "C8 and C9 address the same gap from complementary angles; merging them yields a single question that covers both the threshold definition and the downstream exception path"
    },
    {
      "id": "Q6",
      "question": "What event or condition triggers the start of this measurement workflow, and what signal or output marks its completion so that the next downstream process can begin?",
      "targets": ["Workflow Triggers and Boundaries"],
      "source_ids": ["C12"],
      "selection_reason": "C12 directly addresses the missing start and end boundary information needed to scope the process model and connect it to adjacent workflows"
    }
  ]
}
